import pathlib,os,subprocess,json,time,hashlib,sys
root=pathlib.Path('/home/yan/src/quod');e=root/'doc/evidence/voxel-world-20261016/review-fixes-01'/sys.argv[1];e.mkdir()
files=subprocess.check_output(['git','ls-files','-m','-o','--exclude-standard'],cwd=root,text=True).splitlines()
files=sorted({n for n in files if n.split('/')[0] in {'src','test','native','include','priv','client','ui','scripts'} and (root/n).is_file()})
(e/'source-manifest.json').write_text(json.dumps({n:hashlib.sha256((root/n).read_bytes()).hexdigest() for n in files},indent=2)+'\n')
env=dict(os.environ,PATH='/home/yan/.asdf/shims:/home/yan/.cargo/bin:'+os.environ['PATH'],CARGO_NET_OFFLINE='true',ERL_FLAGS='+S 4:4 +SDio 2 +SDcpu 2')
for k in ['LD_LIBRARY_PATH','LD_PRELOAD','DEBUG']:env.pop(k,None)
a=sys.argv[2:];t=time.monotonic()
with (e/'run.log').open('xb') as f:r=subprocess.run(a,cwd=root,env=env,stdout=f,stderr=subprocess.STDOUT)
x={'command':a,'exit':r.returncode,'seconds':round(time.monotonic()-t,2)};(e/'receipt.json').write_text(json.dumps(x,indent=2)+'\n');print(json.dumps(x));print((e/'run.log').read_text()[-6000:]);sys.exit(r.returncode)
